mapper.select:
SELECT * FROM agent
WHERE tenant_id = #{tenantId}
  AND name = #{name}
  AND is_deleted = 0
ORDER BY id ASC

SELECT * FROM agent

    is_deleted = 0
    AND tenant_id = #{tenantId}
    AND status = #{status}
    AND kind = #{kind}

        AND id IN (
            SELECT sm.agent_id FROM squad_member sm

            JOIN squad s ON s.id = sm.squad_id AND s.is_deleted = 0

                sm.squad_id IN
                #{sqid}
                AND sm.tenant_id = #{tenantId}

        )


ORDER BY id DESC LIMIT #{offset}, #{limit}

SELECT a.* FROM agent a
JOIN agent_version av ON a.online_version_id = av.id AND av.status = 'APPROVED' AND av.is_deleted = 0
WHERE a.tenant_id = #{tenantId}
  AND av.role_code = #{roleCode}
  AND a.is_deleted = 0
ORDER BY a.id ASC

SELECT * FROM agent
WHERE tenant_id = #{tenantId} AND is_deleted = 0 AND id IN
#{aid}
